const steps=[
 ['Mensagem recebida','Uma conversa vira oportunidade.','Telegram identifica pelo chat_id. No simulador, o telefone de teste identifica o lead.','Entrada registrada','“Olá, quero automatizar meu atendimento.”','Identidade + histórico'],
 ['Contexto reunido','A conversa continua de onde parou.','O Supabase reúne perfil, histórico e responsável. A memória da IA conserva o contexto recente.','Cadastro atualizado','Nome, empresa e necessidade passam a acompanhar o contato.','CRM próprio'],
 ['IA conversa','Perguntas curtas, fatos com evidência.','Claude extrai necessidade, prazo e decisão. O validador confere as evidências antes de aceitar os dados.','Necessidade identificada','“Qual parte do atendimento mais ocupa sua equipe?”','Claude + validação'],
 ['Regras qualificam','Uma decisão que a equipe consegue explicar.','As regras configuradas no CRM calculam os pontos. Regras obrigatórias e a nota para quente orientam a passagem ao vendedor.','Qualificação explicável','Aderência, necessidade, prazo e decisão têm critérios editáveis.','Regras no banco'],
 ['Próximo passo','Cada intenção tem um caminho.','Se o lead pedir reunião enquanto a IA atende, ela oferece horários disponíveis. A reserva só é confirmada após a gravação no banco.','Agenda própria','O lead escolhe uma opção. O banco verifica o horário novamente.','Reserva transacional'],
 ['Humano com contexto','O vendedor recebe a conversa inteira.','Ao ficar quente, a IA sai e o fluxo 03 prepara o aviso no Slack. O responsável abre a conversa pelo link e assume o atendimento.','Passagem ao vendedor','Resumo, motivos da pontuação, últimas mensagens e próxima ação.','CRM + Slack']
];
const scenes={journey:{label:'Jornada completa',path:[0,1,2,3,4,5]},meeting:{label:'Pedido de reunião',path:[0,1,2,4]},human:{label:'Lead quente',path:[0,1,2,3,5]}};
const icons=['↗','▤','✦','≋','▦','◎'];
export function mountJourney(root){
 let scene='journey',cursor=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,elapsed=0,last=performance.now(),frame;
 const selected=()=>scenes[scene].path[cursor];
 root.innerHTML=`<section class="oj" aria-label="Apresentação da jornada Órbita"><header class="oj-head"><div><span class="oj-eyebrow">ÓRBITA / VISÃO DO PROJETO</span><h2>Uma conversa.<br><span>O próximo passo certo.</span></h2><p>Do primeiro contato ao vendedor, com contexto em cada etapa.</p></div><div class="oj-mode"><span class="oj-dot"></span> Apresentação ilustrativa<small>Não envia mensagens nem altera leads.</small></div></header><div class="oj-tabs" aria-label="Cenário da apresentação">${Object.entries(scenes).map(([key,s])=>`<button data-scene="${key}" aria-pressed="${key==='journey'}">${s.label}</button>`).join('')}</div><div class="oj-stage"><div class="oj-map"><div class="oj-map-label"><span>DA ENTRADA À AÇÃO</span><span>01 — 06</span></div><div class="oj-track"><svg viewBox="0 0 760 330" preserveAspectRatio="none" aria-hidden="true"><path d="M125 72 H635 Q715 72 715 165 T635 258 H125"/><path class="oj-current" d="M125 72 H635 Q715 72 715 165 T635 258 H125"/></svg>${steps.map((s,i)=>`<button class="oj-node oj-n${i}" data-step="${i}" aria-label="Etapa ${i+1}: ${s[0]}"><span class="oj-node-icon">${icons[i]}</span><span class="oj-node-num">0${i+1}</span><strong>${s[0]}</strong><small>${s[5]}</small></button>`).join('')}</div><div class="oj-source"><span>SUPABASE</span><p>Perfil · Conversa · Regras · Agenda · Responsável</p><b>Uma fonte de dados para toda a operação</b></div></div><aside class="oj-detail" aria-live="off"><span class="oj-eyebrow" id="oj-count"></span><h3 id="oj-title"></h3><p id="oj-description"></p><div class="oj-preview"><span id="oj-status"></span><p id="oj-example"></p><small>Exemplo narrativo · sem dados de clientes</small></div><div class="oj-guard"><span>↳</span><p id="oj-guard"></p></div></aside></div><div class="oj-controls"><button data-control="play"></button><button data-control="next">Próxima etapa →</button><button data-control="reset" aria-label="Reiniciar apresentação">↺ Reiniciar</button><span class="oj-progress"><i></i></span><button data-control="focus" aria-pressed="false">Expandir apresentação</button></div><p class="oj-caption">Agenda e passagem ao humano são caminhos condicionais. Nem todo contato agenda ou se torna quente. Clique em qualquer etapa para explorar.</p><div class="oj-bottom"><article><span class="oj-eyebrow">01 / CONEXÕES</span><h3>Um processo, três fluxos.</h3><ul><li><b>Atendimento</b><span>Telegram e simulador → IA → CRM</span></li><li><b>Entrega por evento</b><span>Resposta pronta → Telegram, sem relógio</span></li><li><b>Passagem ao humano</b><span>Lead quente → responsável no Slack</span></li></ul><p class="oj-footnote">WhatsApp oficial: etapa futura. O simulador reproduz a experiência dentro do CRM.</p></article><article><span class="oj-eyebrow">02 / CONTROLE</span><h3>O contexto chega antes da resposta.</h3><ul><li><b>Vendedor</b><span>Carteira, conversa, pausa da IA e agenda</span></li><li><b>Administrador</b><span>Equipe, distribuição, regras e etapas</span></li><li><b>Gestão</b><span>Atendidos, reuniões, conversão e SLA</span></li></ul><p class="oj-footnote">Os indicadores reais ficam na Visão geral. Esta apresentação não simula resultados comerciais.</p></article></div><details class="oj-risks"><summary>Decisões de projeto e limites para explicar</summary><div><p><b>IA com evidências.</b> Extração estruturada e validação reduzem erros; ainda exigem revisão e testes adversariais.</p><p><b>Humano no controle.</b> Pausa e versão bloqueiam respostas antigas. Uma mensagem já em trânsito pode chegar.</p><p><b>Agenda protegida.</b> Reserva transacional evita disputa pelo mesmo horário. Alterações precisam ser comunicadas ao cliente.</p><p><b>Operação por eventos.</b> Não há consulta periódica no n8n. Falhas de envio exigem conferência e recuperação.</p><p><b>Dados por carteira.</b> Supabase Auth e RLS limitam o acesso. Retenção, backup e tratamento de dados precisam fazer parte da operação.</p><p><b>Ferramenta específica.</b> CRM e agenda próprios reduzem o escopo. O custo total inclui infraestrutura, IA e manutenção.</p></div></details><footer class="oj-links"><a href="https://autoconfi.app.n8n.cloud/workflow/i8MOp5VaXEcng8SZ" target="_blank" rel="noopener">01 · Atendimento ↗</a><a href="https://autoconfi.app.n8n.cloud/workflow/DS09OVYC0j9mR1mU" target="_blank" rel="noopener">02 · Entrega ↗</a><a href="https://autoconfi.app.n8n.cloud/workflow/ZbaXLf4MTCcGTmX9" target="_blank" rel="noopener">03 · Humano ↗</a><a href="./fluxo.html" target="_blank" rel="noopener">Abrir apresentação separada ↗</a></footer></section>`;
 const q=s=>root.querySelector(s);
 const guards=['Evento único evita duplicar a mesma entrada.','Funcionário vê apenas a carteira autorizada.','O modelo extrai fatos; não decide a nota.','Pontuação e critérios vêm das configurações atuais.','Não há confirmação antes de reservar o horário.','A IA interrompe o atendimento ao transferir.'];
 function draw(){const n=selected(),s=steps[n];root.querySelectorAll('[data-step]').forEach(b=>{const i=+b.dataset.step;b.classList.toggle('active',i===n);b.classList.toggle('in-path',scenes[scene].path.includes(i));b.setAttribute('aria-pressed',String(i===n))});root.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scene===scene)));q('#oj-count').textContent=`ETAPA 0${n+1} / ${scenes[scene].label.toUpperCase()}`;q('#oj-title').textContent=s[1];q('#oj-description').textContent=s[2];q('#oj-status').textContent=s[3];q('#oj-example').textContent=s[4];q('#oj-guard').textContent=guards[n];q('[data-control=play]').textContent=playing?'Ⅱ Pausar animação':'▶ Reproduzir';q('.oj').classList.toggle('is-playing',playing);q('.oj-progress i').style.width=`${(cursor+1)/scenes[scene].path.length*100}%`;}
 function move(){cursor=(cursor+1)%scenes[scene].path.length;elapsed=0;draw()}
 root.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{scene=b.dataset.scene;cursor=0;elapsed=0;draw()});
 root.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const n=+b.dataset.step;if(!scenes[scene].path.includes(n))scene='journey';cursor=scenes[scene].path.indexOf(n);playing=false;elapsed=0;draw()});
 q('[data-control=play]').onclick=()=>{playing=!playing;elapsed=0;draw()};q('[data-control=next]').onclick=()=>{playing=false;move()};q('[data-control=reset]').onclick=()=>{cursor=0;elapsed=0;draw()};
 q('[data-control=focus]').onclick=e=>{const expanded=q('.oj').classList.toggle('oj-expanded');e.target.setAttribute('aria-pressed',String(expanded));e.target.textContent=expanded?'Recolher apresentação':'Expandir apresentação'};
 function tick(now){if(!root.isConnected)return;const delta=now-last;last=now;if(playing&&!document.hidden){elapsed+=Math.min(delta,1000);if(elapsed>=5500)move()}frame=requestAnimationFrame(tick)}
 draw();frame=requestAnimationFrame(tick);
 return()=>cancelAnimationFrame(frame);
}
